import os
from datetime import datetime


class InterestRate(PythonData):
    def GetSource(self, config, date, isLiveMode):
        path = os.path.join(
            Globals.DataFolder,
            "alternative",
            "interest-rate",
            "usa",
            "interest-rate.csv",
        )
        return SubscriptionDataSource(
            path, SubscriptionTransportMedium.LocalFile
        )

    def Reader(self, config, line, date, isLiveMode):
        if not line or line.startswith("DATE,"):
            return None

        fields = line.strip().split(",")
        if len(fields) < 2:
            return None

        try:
            point = InterestRate()
            point.Symbol = config.Symbol
            point.Time = datetime.strptime(fields[0], "%Y-%m-%d")
            point.Value = float(fields[1])
            return point
        except (TypeError, ValueError):
            return None


class RateHikeRiskOffAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2004, 1, 2)
        self.SetEndDate(2008, 12, 31)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.rate = self.AddData(
            InterestRate, "USA-INTEREST-RATE", Resolution.Daily
        ).Symbol

        self.previous_rate = None
        self.risk_off = False
        self.flat_trading_days = 0

    def OnData(self, data):
        hike_today = False
        rate_point = data[self.rate] if data.ContainsKey(self.rate) else None
        if rate_point is not None:
            current_rate = rate_point.Value
            if current_rate is not None:
                if (
                    self.previous_rate is not None
                    and current_rate > self.previous_rate
                ):
                    self.Liquidate(self.spy)
                    self.risk_off = True
                    self.flat_trading_days = 0
                    hike_today = True
                self.previous_rate = current_rate

        spy_bar = data.Bars[self.spy] if data.Bars.ContainsKey(self.spy) else None

        if self.risk_off:
            if not hike_today and spy_bar is not None:
                self.flat_trading_days += 1
                if self.flat_trading_days >= 30:
                    self.SetHoldings(self.spy, 1)
                    self.risk_off = False
            return

        if spy_bar is not None and not self.Portfolio[self.spy].Invested:
            self.SetHoldings(self.spy, 1)

