        self.SetStartDate(2004, 1, 2)
        self.SetEndDate(2008, 12, 31)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.rate_symbol = self.AddData(UsaInterestRate, "USA-INTEREST-RATE").Symbol

        self.previous_rate = None
        self.is_flat = False
        self.flat_trading_days_remaining = 0
        self.hike_date = None
        self.initial_position_established = False

    def OnData(self, data):
        rate_point = None
        try:
            rate_points = data.Get(UsaInterestRate)
            if rate_points is not None and rate_points.ContainsKey(self.rate_symbol):
                rate_point = rate_points[self.rate_symbol]
        except (AttributeError, KeyError, TypeError):
            rate_point = None

        if rate_point is not None and rate_point.Value is not None:
            current_rate = float(rate_point.Value)
            if self.previous_rate is not None and current_rate > self.previous_rate:
                if self.Portfolio[self.spy].Invested:
                    self.Liquidate(self.spy)
                self.is_flat = True
                self.flat_trading_days_remaining = 30
                self.hike_date = self.Time.date()
            self.previous_rate = current_rate

        spy_bar = None
        try:
            spy_bar = data.Bars[self.spy] if data.Bars.ContainsKey(self.spy) else None
        except (AttributeError, KeyError, TypeError):
            spy_bar = None

        if spy_bar is None:
            return

        if self.is_flat:
            if self.hike_date is not None and self.Time.date() != self.hike_date:
                self.flat_trading_days_remaining -= 1
                if self.flat_trading_days_remaining <= 0:
                    self.SetHoldings(self.spy, 1.0)
                    self.is_flat = False
                    self.hike_date = None
                    self.initial_position_established = True
            return

        if not self.initial_position_established:
            self.SetHoldings(self.spy, 1.0)
            self.initial_position_established = True

