class RateHikeRiskOffAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2004, 1, 2)
        self.SetEndDate(2008, 12, 31)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.rate_symbol = self.AddData(
            UsaInterestRate, "USA-INTEREST-RATE", Resolution.Daily
        ).Symbol

        self.previous_rate = None
        self.is_flat = False
        self.flat_trading_days = 0
        self.hike_date = None

    def OnData(self, data):
        hike_today = False
        rate_data = data[self.rate_symbol] if data.ContainsKey(self.rate_symbol) else None

        if rate_data is not None and not rate_data.IsFillForward:
            current_rate = rate_data.Value
            if current_rate is not None:
                if self.previous_rate is not None and current_rate > self.previous_rate:
                    self.Liquidate(self.spy)
                    self.is_flat = True
                    self.flat_trading_days = 0
                    self.hike_date = self.Time.date()
                    hike_today = True
                self.previous_rate = current_rate

        spy_bar = data.Bars[self.spy] if data.Bars.ContainsKey(self.spy) else None
        if spy_bar is None:
            return

        if self.is_flat:
            if not hike_today and (
                self.hike_date is None or self.Time.date() > self.hike_date
            ):
                self.flat_trading_days += 1
                if self.flat_trading_days >= 30:
                    self.SetHoldings(self.spy, 1)
                    self.is_flat = False
            return

        if not self.Portfolio[self.spy].Invested:
            self.SetHoldings(self.spy, 1)

