class FrontMonthFuturesDayTradeAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2013, 10, 7)
        self.SetEndDate(2013, 10, 8)
        self.SetCash(1000000)

        future = self.AddFuture(Futures.Indices.SP500EMini, Resolution.Minute)
        future.SetFilter(0, 180)

        self._session_date = None
        self._closes_at_945 = {}

    def OnData(self, data: Slice):
        current_date = self.Time.date()
        if self._session_date != current_date:
            self._session_date = current_date
            self._closes_at_945 = {}

        current_time = self.Time.time()

        if current_time.hour == 9 and current_time.minute == 45:
            for symbol, bar in data.Bars.items():
                if symbol.SecurityType == SecurityType.Future and bar is not None:
                    self._closes_at_945[symbol] = bar.Close

        if current_time.hour == 10 and current_time.minute == 0:
            front_month = None
            for chain in data.FutureChains.Values:
                contracts = [contract for contract in chain.Contracts.Values if contract is not None]
                if not contracts:
                    continue
                chain_front = min(contracts, key=lambda contract: contract.Expiry)
                if front_month is None or chain_front.Expiry < front_month.Expiry:
                    front_month = chain_front

            if front_month is None:
                return

            symbol = front_month.Symbol
            bar_at_1000 = data.Bars[symbol] if data.Bars.ContainsKey(symbol) else None
            close_at_945 = self._closes_at_945.get(symbol)
            if bar_at_1000 is None or close_at_945 is None:
                return

            if bar_at_1000.Close > close_at_945:
                self.MarketOrder(symbol, 1)

        if current_time.hour == 15 and current_time.minute == 0:
            for security in self.Securities.Values:
                if security.Type != SecurityType.Future:
                    continue
                quantity = security.Holdings.Quantity
                if quantity != 0:
                    self.MarketOrder(security.Symbol, -quantity)

