class FrontMonthFuturesDayTradeAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2013, 10, 7)
        self.SetEndDate(2013, 10, 8)
        self.SetCash(1_000_000)

        future = self.AddFuture(Futures.Indices.SP500EMini, Resolution.Minute)
        future.SetFilter(0, 180)
        self.future_symbol = future.Symbol

        self.closes_at_945 = {}
        self.entry_checked_dates = set()
        self.exit_checked_dates = set()

    def OnData(self, data):
        current_date = self.Time.date()

        if self.Time.hour == 9 and self.Time.minute == 45:
            daily_closes = {}
            if data is not None and data.Bars is not None:
                for symbol, bar in data.Bars.items():
                    if (
                        symbol is not None
                        and symbol.SecurityType == SecurityType.Future
                        and bar is not None
                        and bar.Close is not None
                    ):
                        daily_closes[symbol] = bar.Close
            self.closes_at_945[current_date] = daily_closes

        if (
            self.Time.hour == 10
            and self.Time.minute == 0
            and current_date not in self.entry_checked_dates
        ):
            self.entry_checked_dates.add(current_date)
            self.TryEnterFrontMonth(data, current_date)

        if (
            self.Time.hour == 15
            and self.Time.minute == 0
            and current_date not in self.exit_checked_dates
        ):
            self.exit_checked_dates.add(current_date)
            self.CloseFuturesPositions()

    def TryEnterFrontMonth(self, data, current_date):
        if data is None or data.FutureChains is None:
            return

        chain = None
        if data.FutureChains.ContainsKey(self.future_symbol):
            chain = data.FutureChains[self.future_symbol]
        if chain is None:
            return

        contracts = [contract for contract in chain if contract is not None]
        if not contracts:
            return

        front_month = min(contracts, key=lambda contract: contract.Expiry)
        symbol = front_month.Symbol
        closes = self.closes_at_945.get(current_date)
        if closes is None or symbol not in closes:
            return
        if data.Bars is None or not data.Bars.ContainsKey(symbol):
            return

        bar = data.Bars[symbol]
        if bar is None or bar.Close is None:
            return
        if bar.Close > closes[symbol]:
            self.MarketOrder(symbol, 1)

    def CloseFuturesPositions(self):
        for security in self.Securities.Values:
            if (
                security is not None
                and security.Type == SecurityType.Future
                and security.Invested
            ):
                quantity = security.Holdings.Quantity
                if quantity != 0:
                    self.MarketOrder(security.Symbol, -quantity)

