class FrontMonthFuturesDayTrade(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2013, 10, 7)
        self.SetEndDate(2013, 10, 8)
        self.SetCash(1_000_000)

        future = self.AddFuture(Futures.Indices.SP500EMini, Resolution.Minute)
        future.SetFilter(0, 180)
        self._canonical_symbol = future.Symbol

        self._session_date = None
        self._closes_at_945 = {}
        self._entry_checked = False

        self.Schedule.On(
            self.DateRules.EveryDay(self._canonical_symbol),
            self.TimeRules.At(15, 0),
            self._close_futures_positions,
        )

    def OnData(self, data: Slice):
        current_date = self.Time.date()
        if current_date != self._session_date:
            self._session_date = current_date
            self._closes_at_945 = {}
            self._entry_checked = False

        if self.Time.hour == 9 and self.Time.minute == 45:
            if data is None or data.Bars is None:
                return
            for symbol, bar in data.Bars.items():
                if (
                    symbol is not None
                    and symbol.SecurityType == SecurityType.Future
                    and bar is not None
                    and bar.Close is not None
                ):
                    self._closes_at_945[symbol] = bar.Close
            return

        if self.Time.hour != 10 or self.Time.minute != 0 or self._entry_checked:
            return

        self._entry_checked = True
        if data is None or data.FutureChains is None or data.Bars is None:
            return
        if not data.FutureChains.ContainsKey(self._canonical_symbol):
            return

        chain = data.FutureChains[self._canonical_symbol]
        if chain is None:
            return

        contracts = [contract for contract in chain if contract is not None]
        if not contracts:
            return

        front_month = min(contracts, key=lambda contract: contract.Expiry)
        symbol = front_month.Symbol
        if symbol is None or symbol not in self._closes_at_945:
            return
        if not data.Bars.ContainsKey(symbol):
            return

        bar = data.Bars[symbol]
        if bar is None or bar.Close is None:
            return

        if bar.Close > self._closes_at_945[symbol]:
            self.MarketOrder(symbol, 1)

    def _close_futures_positions(self):
        for holding in self.Portfolio.Values:
            if (
                holding is not None
                and holding.Symbol.SecurityType == SecurityType.Future
                and holding.Invested
            ):
                self.MarketOrder(holding.Symbol, -holding.Quantity)

