class FrontMonthFuturesDayTrade(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2013, 10, 7)
        self.SetEndDate(2013, 10, 8)
        self.SetCash(1000000)

        future = self.AddFuture(Futures.Indices.SP500EMini, Resolution.Minute)
        future.SetFilter(0, 180)
        self.future_symbol = future.Symbol

        self.open_945 = {}
        self.current_date = None
        self.entry_checked = False
        self.exit_checked = False

    def OnData(self, slice):
        today = self.Time.date()
        if self.current_date != today:
            self.current_date = today
            self.open_945.clear()
            self.entry_checked = False
            self.exit_checked = False

        hour = self.Time.hour
        minute = self.Time.minute

        if hour == 9 and minute == 45:
            chain = slice.FutureChains.get(self.future_symbol)
            if chain is not None:
                for contract in chain.Contracts.Values:
                    bar = slice.Bars.get(contract.Symbol)
                    if bar is not None and bar.Close is not None:
                        self.open_945[contract.Symbol] = bar.Close

        if hour == 10 and minute == 0 and not self.entry_checked:
            self.entry_checked = True
            chain = slice.FutureChains.get(self.future_symbol)
            if chain is not None:
                contracts = list(chain.Contracts.Values)
                if contracts:
                    front_month = min(contracts, key=lambda contract: contract.Expiry)
                    bar = slice.Bars.get(front_month.Symbol)
                    close_945 = self.open_945.get(front_month.Symbol)
                    if (
                        bar is not None
                        and bar.Close is not None
                        and close_945 is not None
                        and bar.Close > close_945
                    ):
                        self.MarketOrder(front_month.Symbol, 1)

        if hour == 15 and minute == 0 and not self.exit_checked:
            self.exit_checked = True
            for holding in self.Portfolio.Values:
                if (
                    holding.Invested
                    and holding.Type == SecurityType.Future
                    and holding.Quantity != 0
