class FrontMonthFuturesDayTradeAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2013, 10, 7)
        self.SetEndDate(2013, 10, 8)
        self.SetCash(1000000)

        future = self.AddFuture(Futures.Indices.SP500EMini, Resolution.Minute)
        future.SetFilter(0, 180)
        self._future_symbol = future.Symbol

        self._session_date = None
        self._closes_at_0945 = {}
        self._entry_checked = False
        self._exit_checked = False

    def OnData(self, data: Slice):
        session_date = self.Time.date()
        if session_date != self._session_date:
            self._session_date = session_date
            self._closes_at_0945 = {}
            self._entry_checked = False
            self._exit_checked = False

        hour = self.Time.hour
        minute = self.Time.minute

        if hour == 9 and minute == 45:
            self._record_0945_closes(data)

        if hour == 10 and minute == 0 and not self._entry_checked:
            self._entry_checked = True
            self._try_enter_front_month(data)

        if hour == 15 and minute == 0 and not self._exit_checked:
            self._exit_checked = True
            self._close_futures_positions()

    def _record_0945_closes(self, data: Slice):
        chain = data.FutureChains.get(self._future_symbol)
        if chain is None:
            return

        for contract in chain:
            bar = data.Bars.get(contract.Symbol)
            if bar is not None:
                self._closes_at_0945[contract.Symbol] = bar.Close

    def _try_enter_front_month(self, data: Slice):
        chain = data.FutureChains.get(self._future_symbol)
        if chain is None:
            return

        contracts = [contract for contract in chain if contract is not None]
        if not contracts:
            return

        front_month = min(contracts, key=lambda contract: contract.Expiry)
        bar = data.Bars.get(front_month.Symbol)
        close_at_0945 = self._closes_at_0945.get(front_month.Symbol)
        if bar is None or close_at_0945 is None:
            return

        if bar.Close > close_at_0945:
            self.MarketOrder(front_month.Symbol, 1)

    def _close_futures_positions(self):
        for holding in self.Portfolio.Values:
            if (
                holding.Type == SecurityType.Future
                and holding.Invested
                and holding.Quantity != 0
            ):
                self.MarketOrder(holding.Symbol, -holding.Quantity)

