class AaplOptionExerciseSplitAlgorithm(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2014, 6, 6)
        self.set_end_date(2014, 6, 9)
        self.set_cash(100000)

        equity = self.add_equity("AAPL", Resolution.MINUTE)
        self.aapl = equity.symbol

        option = self.add_option("AAPL", Resolution.MINUTE)
        self.aapl_option = option.symbol
        option.set_filter(
            lambda universe: universe.include_weeklys()
            .strikes(-10, 10)
            .expiration(timedelta(days=0), timedelta(days=2))
        )

        self.option_purchased = False
        self.stock_sold = False

    def on_data(self, slice):
        if self.time.hour != 10 or self.time.minute != 0:
            return

        if self.time.date() == datetime(2014, 6, 6).date():
            self._buy_expiring_call(slice)
        elif self.time.date() == datetime(2014, 6, 9).date():
            self._sell_aapl_holdings()

    def _buy_expiring_call(self, slice):
        if self.option_purchased or slice is None or slice.option_chains is None:
            return

        chain = slice.option_chains.get(self.aapl_option)
        if chain is None:
            return

        calls = [
            contract
            for contract in chain
            if contract is not None
            and contract.right == OptionRight.CALL
            and contract.expiry.date() == self.time.date()
        ]
        if not calls:
            return

        contract = min(calls, key=lambda candidate: candidate.strike)
        if contract.symbol is None:
            return

        self.market_order(contract.symbol, 1)
        self.option_purchased = True

    def _sell_aapl_holdings(self):
        if self.stock_sold or self.aapl is None:
            return

        holdings = self.portfolio[self.aapl]
        if holdings is None:
            return

        quantity = holdings.quantity
        if quantity is None or quantity <= 0:
            return

        self.market_order(self.aapl, -quantity)
        self.stock_sold = True

