class LossThrottledSmaCrossAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2007, 1, 3)
        self.SetEndDate(2011, 12, 31)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.fast_sma = self.SMA(self.spy, 20, Resolution.Daily)
        self.slow_sma = self.SMA(self.spy, 60, Resolution.Daily)

        self.previous_fast = None
        self.previous_slow = None
        self.next_entry_percentage = 0.80
        self.pending_order = None

        self.entry_fill_value = 0.0
        self.entry_fill_quantity = 0.0
        self.entry_fill_price = None
        self.exit_fill_value = 0.0
        self.exit_fill_quantity = 0.0

    def OnData(self, data):
        if data is None or self.spy not in data.Bars:
            return
        bar = data.Bars[self.spy]
        if bar is None or bar.Close is None:
            return
        if not self.fast_sma.IsReady or not self.slow_sma.IsReady:
            return

        current_fast = self.fast_sma.Current.Value
        current_slow = self.slow_sma.Current.Value
        if current_fast is None or current_slow is None:
            return

        if self.previous_fast is not None and self.previous_slow is not None:
            crossed_above = (
                self.previous_fast <= self.previous_slow
                and current_fast > current_slow
            )
            crossed_below = (
                self.previous_fast >= self.previous_slow
                and current_fast < current_slow
            )

            if self.pending_order is None:
                if crossed_above and not self.Portfolio[self.spy].Invested:
                    self.entry_fill_value = 0.0
                    self.entry_fill_quantity = 0.0
                    self.entry_fill_price = None
                    self.pending_order = "ENTRY"
                    self.SetHoldings(
                        self.spy,
                        self.next_entry_percentage,
                        False,
                        "ENTRY",
                    )
                elif crossed_below and self.Portfolio[self.spy].Invested:
                    self.exit_fill_value = 0.0
                    self.exit_fill_quantity = 0.0
                    self.pending_order = "EXIT"
                    self.Liquidate(self.spy, "EXIT")

        self.previous_fast = current_fast
        self.previous_slow = current_slow

    def OnOrderEvent(self, order_event):
        if order_event is None or order_event.Symbol != self.spy:
            return

        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return
        tag = order.Tag

        if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            fill_price = order_event.FillPrice
            fill_quantity = abs(float(order_event.FillQuantity))
            if fill_price is not None and fill_quantity > 0:
                if tag == "ENTRY":
                    self.entry_fill_value += float(fill_price) * fill_quantity
                    self.entry_fill_quantity += fill_quantity
                elif tag == "EXIT":
                    self.exit_fill_value += float(fill_price) * fill_quantity
                    self.exit_fill_quantity += fill_quantity

        if order_event.Status == OrderStatus.Filled:
            if tag == "ENTRY":
                if self.entry_fill_quantity > 0:
                    self.entry_fill_price = (
                        self.entry_fill_value / self.entry_fill_quantity
                    )
                self.pending_order = None
            elif tag == "EXIT":
                if self.exit_fill_quantity > 0 and self.entry_fill_price is not None:
                    exit_fill_price = (
                        self.exit_fill_value / self.exit_fill_quantity
                    )
                    if exit_fill_price < self.entry_fill_price:
                        self.next_entry_percentage = max(
                            0.05, self.next_entry_percentage / 2.0
                        )
                    else:
