class LossThrottledSmaCrossAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2007, 1, 3)
        self.SetEndDate(2011, 12, 31)
        self.SetCash(100000)

        self.symbol = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.fast = self.SMA(self.symbol, 20, Resolution.Daily)
        self.slow = self.SMA(self.symbol, 60, Resolution.Daily)

        self.previous_fast = None
        self.previous_slow = None
        self.next_entry_percentage = 0.80
        self.active_entry_percentage = None
        self.entry_fill_price = None

        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_fill_value = 0.0
        self.entry_fill_quantity = 0.0
        self.exit_fill_value = 0.0
        self.exit_fill_quantity = 0.0

    def OnData(self, data):
        if data is None or not data.ContainsKey(self.symbol):
            return
        bar = data[self.symbol]
        if bar is None or bar.Close is None:
            return
        if not self.fast.IsReady or not self.slow.IsReady:
            return

        fast = self.fast.Current.Value
        slow = self.slow.Current.Value
        if fast is None or slow is None:
            return

        if self.previous_fast is not None and self.previous_slow is not None:
            crossed_above = self.previous_fast <= self.previous_slow and fast > slow
            crossed_below = self.previous_fast >= self.previous_slow and fast < slow

            if (
                crossed_above
                and not self.Portfolio[self.symbol].Invested
                and self.entry_order_id is None
                and self.exit_order_id is None
            ):
                percentage = max(0.05, self.next_entry_percentage)
                quantity = self.CalculateOrderQuantity(self.symbol, percentage)
                if quantity != 0:
                    ticket = self.MarketOrder(self.symbol, quantity)
                    if ticket is not None:
                        self.entry_order_id = ticket.OrderId
                        self.active_entry_percentage = percentage
                        self.entry_fill_value = 0.0
                        self.entry_fill_quantity = 0.0

            elif (
                crossed_below
                and self.Portfolio[self.symbol].Invested
                and self.entry_order_id is None
                and self.exit_order_id is None
            ):
                quantity = -self.Portfolio[self.symbol].Quantity
                if quantity != 0:
                    ticket = self.MarketOrder(self.symbol, quantity)
                    if ticket is not None:
                        self.exit_order_id = ticket.OrderId
                        self.exit_fill_value = 0.0
                        self.exit_fill_quantity = 0.0

        self.previous_fast = fast
        self.previous_slow = slow

    def OnOrderEvent(self, orderEvent):
        if orderEvent is None or orderEvent.FillPrice is None:
            return
        if orderEvent.Status not in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            return

        fill_quantity = abs(orderEvent.FillQuantity)
        if fill_quantity == 0:
            return

        if orderEvent.OrderId == self.entry_order_id:
            self.entry_fill_value += orderEvent.FillPrice * fill_quantity
            self.entry_fill_quantity += fill_quantity
            if orderEvent.Status == OrderStatus.Filled:
                if self.entry_fill_quantity > 0:
                    self.entry_fill_price = (
                        self.entry_fill_value / self.entry_fill_quantity
                    )
                self.entry_order_id = None

        elif orderEvent.OrderId == self.exit_order_id:
            self.exit_fill_value += orderEvent.FillPrice * fill_quantity
            self.exit_fill_quantity += fill_quantity
            if orderEvent.Status == OrderStatus.Filled:
                exit_fill_price = None
                if self.exit_fill_quantity > 0:
                    exit_fill_price = self.exit_fill_value / self.exit_fill_quantity

                if exit_fill_price is not None and self.entry_fill_price is not None:
                    if exit_fill_price < self.entry_fill_price:
                        prior_percentage = self.active_entry_percentage
                        if prior_percentage is None:
                            prior_percentage = self.next_entry_percentage
                        self.next_entry_percentage = max(0.05, prior_percentage / 2.0)
                    else:
                        self.next_entry_percentage = 0.80

                self.exit_order_id = None
                self.active_entry_percentage = None
                self.entry_fill_price = None

