class FrontMonthFuturesDayTrade(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2013, 10, 7)
        self.SetEndDate(2013, 10, 8)
        self.SetCash(1_000_000)

        self._future = self.AddFuture(
            Futures.Indices.SP500EMini,
            Resolution.Minute,
        )
        self._future.SetFilter(timedelta(days=0), timedelta(days=180))

        self._recorded_date = None
        self._closes_at_0945 = {}

    def OnData(self, data: Slice):
        current_date = self.Time.date()
        if self._recorded_date != current_date:
            self._recorded_date = current_date
            self._closes_at_0945 = {}

        if self.Time.hour == 9 and self.Time.minute == 45:
            for symbol, bar in data.Bars.items():
                if symbol.SecurityType == SecurityType.Future and bar is not None:
                    self._closes_at_0945[symbol] = bar.Close

        if self.Time.hour == 10 and self.Time.minute == 0:
            chain = data.FutureChains.get(self._future.Symbol)
            if chain is not None:
                contracts = list(chain)
                if contracts:
                    front_month = min(contracts, key=lambda contract: contract.Expiry)
                    bar = data.Bars.get(front_month.Symbol)
                    close_at_0945 = self._closes_at_0945.get(front_month.Symbol)
                    if (
                        bar is not None
                        and close_at_0945 is not None
