            Futures.Indices.SP500EMini,
            Resolution.Minute,
        )
        self._future.SetFilter(0, 180)

        self._recorded_date = None
        self._closes_at_0945 = {}

        self.Schedule.On(
            self.DateRules.EveryDay(self._future.Symbol),
            self.TimeRules.At(15, 0),
            self._close_positions,
        )

