            return

        current_date = self.Time.date()
        if self._recorded_date != current_date:
            self._recorded_date = current_date
            self._closes_at_0945 = {}

        hour = self.Time.hour
        minute = self.Time.minute

        chain = None
        if data.FutureChains is not None:
            for candidate in data.FutureChains.Values:
                if candidate is not None and candidate.Symbol == self._future.Symbol:
                    chain = candidate
