                ]
                if calls:
                    contract = min(calls, key=lambda candidate: candidate.Strike)
                    self.MarketOrder(contract.Symbol, 1)

        if (
            not self.stock_sale_attempted
            and self.Time == datetime(2014, 6, 9, 10, 0)
        ):
            self.stock_sale_attempted = True
            holdings = self.Portfolio[self.aapl]
            if holdings is not None and holdings.Quantity != 0:
