            return

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        fast = self.fast.Current.Value
        slow = self.slow.Current.Value
        if fast is None or slow is None:
            return

        if self.previous_fast is not None and self.previous_slow is not None:
            crossed_above = (
                self.previous_fast <= self.previous_slow and fast > slow
            )
            crossed_below = (
                self.previous_fast >= self.previous_slow and fast < slow
            )

            if self.pending_action is None:
                if crossed_above and not self.Portfolio[self.spy].Invested:
                    self.pending_action = "entry"
                    self.fill_value = 0.0
                    self.fill_quantity = 0.0
                    self.SetHoldings(self.spy, self.next_entry_percentage)
                elif crossed_below and self.Portfolio[self.spy].Invested:
                    self.pending_action = "exit"
                    self.fill_value = 0.0
