                    self.entry_fill_price = average_fill
            elif (
                self.pending_action == "exit"
                and average_fill is not None
                and self.entry_fill_price is not None
            ):
                if average_fill < self.entry_fill_price:
                    self.next_entry_percentage = max(
                        0.05, self.next_entry_percentage / 2.0
                    )
                else:
                    self.next_entry_percentage = 0.80
                self.entry_fill_price = None

            self.pending_action = None
            self.fill_value = 0.0
            self.fill_quantity = 0.0
        elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
            self.pending_action = None
            self.fill_value = 0.0
            self.fill_quantity = 0.0

