        if bar is None or bar.Close is None:
            return
        if not self.fast.IsReady or not self.slow.IsReady:
            return

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        if self.previous_fast is not None and self.previous_slow is not None:
            crossed_above = (
                self.previous_fast <= self.previous_slow
                and current_fast > current_slow
            )
            crossed_below = (
                self.previous_fast >= self.previous_slow
                and current_fast < current_slow
            )

            if (
                crossed_above
                and not self.Portfolio[self.spy].Invested
                and self.entry_order_id is None
                and self.exit_order_id is None
            ):
                quantity = self.CalculateOrderQuantity(
                    self.spy, self.next_entry_percentage
                )
                if quantity != 0:
                    ticket = self.MarketOrder(self.spy, quantity)
                    if ticket is not None:
                        self.entry_order_id = ticket.OrderId

            elif (
                crossed_below
                and self.Portfolio[self.spy].Invested
                and self.entry_order_id is None
                and self.exit_order_id is None
            ):
                quantity = -self.Portfolio[self.spy].Quantity
                if quantity != 0:
                    ticket = self.MarketOrder(self.spy, quantity)
                    if ticket is not None:
                        self.exit_order_id = ticket.OrderId

        self.previous_fast = current_fast
        self.previous_slow = current_slow

    def OnOrderEvent(self, order_event):
        if order_event is None or order_event.Symbol != self.spy:
            return
        if order_event.Status not in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            return

        fill_quantity = abs(order_event.FillQuantity)
        fill_price = order_event.FillPrice
        if fill_quantity == 0 or fill_price is None:
            return

        if order_event.OrderId == self.entry_order_id:
            self.entry_fill_value += fill_quantity * fill_price
            self.entry_fill_quantity += fill_quantity
            self.entry_fill_price = (
                self.entry_fill_value / self.entry_fill_quantity
            )
            if order_event.Status == OrderStatus.Filled:
                self.entry_order_id = None

        elif order_event.OrderId == self.exit_order_id:
            self.exit_fill_value += fill_quantity * fill_price
            self.exit_fill_quantity += fill_quantity
            if order_event.Status == OrderStatus.Filled:
                exit_fill_price = (
                    self.exit_fill_value / self.exit_fill_quantity
                )
                if self.entry_fill_price is not None:
                    if exit_fill_price < self.entry_fill_price:
                        self.next_entry_percentage = max(
                            0.05, self.next_entry_percentage / 2.0
                        )
                    else:
                        self.next_entry_percentage = 0.80

                self.exit_order_id = None
                self.entry_fill_value = 0.0
                self.entry_fill_quantity = 0.0
                self.entry_fill_price = None
                self.exit_fill_value = 0.0
                self.exit_fill_quantity = 0.0
